#!/usr/bin/env bash
#
# EasyPhone Orchestrator — Banner de entrada por SSH (MOTD)
# ========================================================
# Instala o logo do EasyPhone e o resumo do host no /etc/update-motd.d,
# exibido após o login via SSH no Ubuntu/Debian Server.
#
# Uso: sudo bash scripts/motd-easyphone.sh
#      sudo bash motd-easyphone.sh   (wrapper na raiz)
#
set -euo pipefail

if [[ $EUID -ne 0 ]]; then
  echo "Execute como root: sudo bash $0" >&2
  exit 1
fi

mkdir -p /etc/update-motd.d

cat > /etc/update-motd.d/01-easyphone <<'EASYPHONE_EOF'
