echo

HOST=$(hostname)
IP=$(hostname -I 2>/dev/null | awk '{print $1}')
UP=$(uptime -p 2>/dev/null | sed 's/^up //')
LOAD=$(cut -d' ' -f1-3 /proc/loadavg)
MEM=$(free -h | awk '/^Mem:/{print $3" / "$2}')
DISK=$(df -h / | awk 'NR==2{print $3" / "$2" ("$5")"}')

printf "  ${L}Servidor:${R} ${V}%-22s${R} ${L}IP:${R}    ${V}%s${R}\n" "$HOST" "$IP"
printf "  ${L}Ativo há:${R} ${V}%-22s${R} ${L}Carga:${R} ${V}%s${R}\n" "$UP" "$LOAD"
printf "  ${L}Memória:${R}  ${V}%-22s${R} ${L}Disco:${R} ${V}%s${R}\n" "$MEM" "$DISK"
if command -v docker >/dev/null 2>&1; then
  RUN=$(docker ps -q 2>/dev/null | wc -l)
  ALL=$(docker ps -aq 2>/dev/null | wc -l)
  printf "  ${L}Contêineres:${R} ${V}%s${R} ${L}rodando de${R} ${V}%s${R}\n" "$RUN" "$ALL"
fi
echo
