chmod 755 /etc/update-motd.d/01-easyphone
chown root:root /etc/update-motd.d/01-easyphone 2>/dev/null || true

# Desliga as mensagens padrão do Ubuntu que poluem a tela
# (reversível: chmod +x no arquivo volta a exibir)
for f in 00-header 10-help-text 10-uname 50-motd-news 50-landscape-sysinfo; do
  if [[ -e "/etc/update-motd.d/$f" ]]; then
    chmod -x "/etc/update-motd.d/$f" 2>/dev/null || true
    echo "Desativado: $f"
  fi
done

echo
echo "Pronto. Prévia:"
/etc/update-motd.d/01-easyphone
echo "Saia e entre de novo pelo SSH para ver no login."
